"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["59712"],{72878(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.oferta_curso.cardinalidade_turnos_incompativel_com_regime","status":422,"titulo":"Quantidade de turnos incompat\xedvel com o regime declarado"},"descricao":{"codigo":"uniplus.configuracao.oferta_curso.cardinalidade_turnos_incompativel_com_regime","requisitos":["UNI-REQ-0137"],"oQueAconteceu":["A quantidade de turnos informada n\xe3o \xe9 a que o `regimeDeTurno` declarado exige:","| Regime declarado | Turnos exigidos |\\n|---|---|\\n| `REGULAR` | exatamente 1 |\\n| `INTEGRAL` | exatamente 2, distintos |","O regime \xe9 **declarado, nunca inferido**. Enviar dois turnos com\\n`regimeDeTurno: \\"REGULAR\\"` \xe9 recusado \u2014 a oferta n\xe3o \xe9 promovida a `INTEGRAL`\\npor conta pr\xf3pria. Isso \xe9 proposital: inferir o regime pela contagem tornaria\\nimposs\xedvel distinguir um turno informado por engano de uma oferta que\\nrealmente funciona em dois per\xedodos.","A mensagem do erro informa quantos turnos o regime exige, sem repetir o regime declarado nem a quantidade enviada."],"comoResolver":["Corrija **o lado que estava errado** \u2014 pode ser o regime ou a lista.","Se a oferta realmente ocupa dois per\xedodos, o regime \xe9 que estava errado:","```json\\n{\\n  \\"regimeDeTurno\\": \\"INTEGRAL\\",\\n  \\"turnos\\": [\\"MATUTINO\\", \\"VESPERTINO\\"]\\n}\\n```","Se ocupa um s\xf3, sobra turno na lista:","```json\\n{\\n  \\"regimeDeTurno\\": \\"REGULAR\\",\\n  \\"turnos\\": [\\"MATUTINO\\"]\\n}\\n```"],"ondeAparece":["Cria\xe7\xe3o de uma oferta de curso","Atualiza\xe7\xe3o de uma oferta de curso"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Oferta curso"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);